<script lang="ts">import{DirectPrintRoute}from'../print/direct.js';import{WebBluetoothTransport,WebUsbTransport}from'../print/browser-transports.js';import{JobJournal}from'../jobs.js';import type{EditorDatabase}from'../persistence/database.js';import type{LabelDocument}from'../model.js';import type{PrinterDefinition,PrinterSdk}from'../print/types.js';export let sdk:PrinterSdk;export let document:LabelDocument;export let printer:PrinterDefinition|undefined;export let database:EditorDatabase;let route:'bluetooth'|'usb'='bluetooth';let service='0000ff00-0000-1000-8000-00805f9b34fb';let write='0000ff02-0000-1000-8000-00805f9b34fb';let notify='0000ff01-0000-1000-8000-00805f9b34fb';let vendorId='0x04f9';let status='';let active:DirectPrintRoute|undefined;let cancellation:AbortController|undefined;
async function print(){if(!printer){status='Select a printer model first.';return}active??=route==='bluetooth'?new DirectPrintRoute(sdk,async()=>new WebBluetoothTransport({service,writeCharacteristic:write,notifyCharacteristic:notify,physicalWriteLimit:20}),'bluetooth',()=>!!(navigator as Navigator&{bluetooth?:unknown}).bluetooth,new JobJournal(database)):new DirectPrintRoute(sdk,async()=>new WebUsbTransport({filters:[{vendorId:Number(vendorId)}]}),'usb',()=>!!(navigator as Navigator&{usb?:unknown}).usb,new JobJournal(database));cancellation=new AbortController();status='Choose a device in the browser prompt…';const result=await active.print({document,printer,copies:1,signal:cancellation.signal,onProgress:p=>status=`${p.phase}: ${p.bytesSent}/${p.totalBytes} bytes`});cancellation=undefined;status=result.outcome==='completed'?'Direct print completed.':`${result.outcome}: ${result.error??'Do not retry until the physical printer is checked.'}`;if(result.outcome==='completed'||result.outcome==='failed'||result.outcome==='cancelled-before-send')active=undefined}
</script>
<section><h2>Direct browser print</h2><label>Route<select bind:value={route}><option value="bluetooth">Web Bluetooth</option><option value="usb">WebUSB</option></select></label>{#if route==='bluetooth'}<details><summary>Bluetooth definition</summary><label>Service UUID<input bind:value={service}></label><label>Write UUID<input bind:value={write}></label><label>Notify UUID<input bind:value={notify}></label></details>{:else}<label>USB vendor ID<input bind:value={vendorId}></label>{/if}<button on:click={print} disabled={!!cancellation}>Choose device & print</button>{#if cancellation}<button on:click={()=>cancellation?.abort()}>Cancel current job</button>{/if}<p aria-live="polite">{status}</p></section><style>section{padding:.75rem;border-top:1px solid #ddd}h2{font-size:.8rem;text-transform:uppercase}label{display:flex;flex-direction:column;font-size:.75rem}</style>
